-- PRCP ZX_CITIC_2026 prcp_data_basic 数据
-- 中信银行 2026 H1 模拟数据（2026-06-30）
-- 38 个节点 × 1 月 = 38 行

SET NAMES utf8mb4;
SET @scheme_id := 2;

-- 0) 幂等检查 + 清理已存在数据
SELECT IF(COUNT(*)>0, CONCAT('EXISTS:', COUNT(*)), 'OK') AS status
FROM prcp_data_basic b
JOIN prcp_coa_node n ON b.coa_node_id=n.id
WHERE n.scheme_id=@scheme_id AND b.is_deleted=0;

DELETE b FROM prcp_data_basic b
JOIN prcp_coa_node n ON b.coa_node_id=n.id
WHERE n.scheme_id=@scheme_id AND b.data_date='2026-06-30';

-- 1) 取 38 个节点的 prcp_coa_node.id
DROP TEMPORARY TABLE IF EXISTS _citic_nodes;
CREATE TEMPORARY TABLE _citic_nodes (
  code VARCHAR(32) PRIMARY KEY,
  name VARCHAR(64),
  id BIGINT NOT NULL,
  level INT,
  is_leaf INT,
  category VARCHAR(16),
  parent_code VARCHAR(32)
) ENGINE=MEMORY;

INSERT INTO _citic_nodes (code, name, id, level, is_leaf, category, parent_code)
SELECT n.node_code, n.node_name, n.id, n.node_level,
       IF(n.node_type LIKE '%LEAF', 1, 0),
       IF(n.node_type LIKE 'ASSET%', 'ASSET', IF(n.node_type LIKE 'LIAB%', 'LIAB', IF(n.node_type LIKE 'EQUITY%', 'EQUITY', 'OTHER'))),
       (SELECT p.node_code FROM prcp_coa_node p WHERE p.id=n.parent_id AND p.is_deleted=0 LIMIT 1)
FROM prcp_coa_node n
WHERE n.scheme_id=@scheme_id AND n.is_deleted=0;

