INSERT INTO prcp_data_basic (
  coa_node_id, data_date, node_code, node_name, node_level, parent_code,
  is_leaf, category, date_offset, offset_unit,
  orig_m1, orig_m2, orig_m3, orig_m4, orig_m5, orig_m6, orig_m7, orig_m8, orig_m9, orig_m10, orig_m11, orig_m12,
  orig_y10, orig_y15, orig_y20, orig_y30,
  rem_m1, rem_m2, rem_m3, rem_m4, rem_m5, rem_m6, rem_m7, rem_m8, rem_m9, rem_m10, rem_m11, rem_m12,
  rem_y10, rem_y15, rem_y20, rem_y30,
  asf_rsf, hqla_factor, current_balance, avg_balance, weighted_rate, interest_amount, risk_weight,
  calc_note, is_deleted, created_by, updated_by)
SELECT coa_node_id, data_date, node_code, node_name, node_level, parent_code,
  is_leaf, category, date_offset, offset_unit,
  orig_m1, orig_m2, orig_m3, orig_m4, orig_m5, orig_m6, orig_m7, orig_m8, orig_m9, orig_m10, orig_m11, orig_m12,
  orig_y10, orig_y15, orig_y20, orig_y30,
  rem_m1, rem_m2, rem_m3, rem_m4, rem_m5, rem_m6, rem_m7, rem_m8, rem_m9, rem_m10, rem_m11, rem_m12,
  rem_y10, rem_y15, rem_y20, rem_y30,
  asf_rsf, hqla_factor, current_balance, avg_balance, weighted_rate, interest_amount, risk_weight,
  calc_note, is_deleted, created_by, updated_by
FROM _citic_basic;

-- 4) 验证
SELECT category, COUNT(*) AS cnt,
       ROUND(SUM(current_balance)/1e8, 0) AS total_yi
FROM prcp_data_basic b
JOIN prcp_coa_node n ON n.id=b.coa_node_id
WHERE n.scheme_id=@scheme_id AND b.is_deleted=0
GROUP BY category;

SELECT is_leaf, COUNT(*) AS cnt
FROM prcp_data_basic b
JOIN prcp_coa_node n ON n.id=b.coa_node_id
WHERE n.scheme_id=@scheme_id AND b.is_deleted=0
GROUP BY is_leaf;

DROP TEMPORARY TABLE IF EXISTS _citic_nodes;
DROP TEMPORARY TABLE IF EXISTS _citic_basic;